===== PARTICIPANT =====
import {
  bowlerChargedExtrasSql,
  bowlerWideRunsSql,
  countsAsBallFacedSql,
  isLegalDeliverySql,
} from '@sport-analytics/contracts';

import { executeQuery, getDatabasePool, type QueryExecutor } from '../../database';
import { standardInningsPredicate } from '../statistics/super-over-scope';

export interface ParticipantRecord {
  participantId: string;
  displayName: string;
}

export interface ParticipantListOptions {
  limit: number;
  fixtureId?: string;
  competitorId?: string;
  name?: string;
  after?: {
    displayName: string;
    participantId: string;
  };
}

export interface ParticipantPage {
  records: ParticipantRecord[];
  hasMore: boolean;
  totalRecords: number;
}

export async function listParticipants(
  options: ParticipantListOptions,
  executor: QueryExecutor = getDatabasePool(),
): Promise<ParticipantPage> {
  // Split so the total reflects the filters (name, fixture/team) but not the
  // cursor position: paging further through the same filtered set must not
  // change how many pages it reports.
  const filterConditions: string[] = [];
  const cursorConditions: string[] = [];
  const values: unknown[] = [];

  if (options.name) {
    values.push(`%${options.name}%`);
    filterConditions.push(`p.display_name ILIKE $${values.length}`);
  }

  if (options.fixtureId || options.competitorId) {
    const squadConditions = ['fs.person_id = p.person_id'];

    if (options.fixtureId) {
      values.push(options.fixtureId);
      squadConditions.push(`fs.fixture_id = $${values.length}::bigint`);
    }

    if (options.competitorId) {
      values.push(options.competitorId);
      squadConditions.push(`fs.team_id = $${values.length}::bigint`);
    }

    filterConditions.push(`
      EXISTS (
        SELECT 1
        FROM fixture_squad fs
        WHERE ${squadConditions.join(' AND ')}
      )
    `);
  }

  if (options.after) {
    values.push(options.after.displayName);
    const nameParameter = values.length;

    values.push(options.after.participantId);
    const idParameter = values.length;

    cursorConditions.push(
      `(display_name, person_id) > ($${nameParameter}::text, $${idParameter}::bigint)`,
    );
  }

  values.push(options.limit + 1);
  const limitParameter = values.length;

  const filterWhere = filterConditions.length > 0 ? `WHERE ${filterConditions.join(' AND ')}` : '';
  const cursorWhere = cursorConditions.length > 0 ? `WHERE ${cursorConditions.join(' AND ')}` : '';

  const result = await executeQuery<ParticipantRecord & { totalRecords: number }>(
    executor,
    `
      WITH filtered_participants AS (
        SELECT
          p.person_id,
          p.display_name,
          COUNT(*) OVER()::integer AS "totalRecords"
        FROM person p
        ${filterWhere}
      )
      SELECT
        person_id::text AS "participantId",
        display_name AS "displayName",
        "totalRecords"
      FROM filtered_participants
      ${cursorWhere}
      ORDER BY display_name ASC, person_id ASC
      LIMIT $${limitParameter}
    `,
    values,
  );

  return {
    records: result.rows.slice(0, options.limit),
    hasMore: result.rows.length > options.limit,
    totalRecords: result.rows[0]?.totalRecords ?? 0,
  };
}

export async function findParticipantById(
  participantId: string,
  executor: QueryExecutor = getDatabasePool(),
): Promise<ParticipantRecord | null> {
  const result = await executeQuery<ParticipantRecord>(
    executor,
    `
      SELECT
        person_id::text AS "participantId",
        display_name AS "displayName"
      FROM person
      WHERE person_id = $1::bigint
    `,
    [participantId],
  );

  return result.rows[0] ?? null;
}

export interface ParticipantFixtureRecord {
  fixtureId: string;
  competitionId: string | null;
  competitionName: string | null;
  ballsPerOver: number;
  scheduledOvers: number | null;
  season: string;
  matchType: string;
  teamType: string;
  gender: string;
  startDate: string;
  endDate: string;
  teamId: string;
  teamName: string;
  role: string | null;
  missingFields: string[];
  standardInningsCount: number;
  acceptedEventCount: number;
  emptyStandardInningsIds: string[];
  runsScored: number | null;
  ballsFaced: number | null;
  fours: number | null;
  sixes: number | null;
  runsConceded: number | null;
  wides: number | null;
  noBalls: number | null;
  legalBallsBowled: number | null;
  wicketsTaken: number | null;
}

export interface ParticipantFixtureListOptions {
  participantId: string;
  limit: number;
  after?: {
    startDate: string;
    fixtureId: string;
  };
}

export interface ParticipantFixturePage {
  records: ParticipantFixtureRecord[];
  hasMore: boolean;
}

/**
 * The fixtures a participant was selected for, newest first, with their batting
 * and bowling figures for each.
 *
 * Participation is squad selection rather than appearance in a delivery, which
 * is the meaning already used elsewhere in this repository and the one a cricket
 * record reflects: a player selected but not called upon still played in the
 * fixture.
 *
 * The figures are aggregated here rather than derived per fixture through the
 * statistics module, because deriving fifty fixtures for one page would cost
 * fifty round trips. The aggregation rules are those the statistics module
 * applies, and a test asserts the two agree:
 *
 *   - only deliveries from accepted submissions are counted;
 *   - a revised delivery is resolved to its latest revision;
 *   - super-over innings are excluded;
 *   - a wide is not a ball faced, but a no-ball is;
 *   - a wide and a no-ball are not legal balls bowled;
 *   - byes and leg byes are not conceded by the bowler, except when run off a
 *     wide, where Law 22.6 makes them wide runs;
 *   - only dismissal kinds crediting the bowler count as wickets.
 *
 * A fixture the participant was selected for but did not bat or bowl in returns
 * null figures rather than being omitted.
 *
 * Nothing may re-read `accepted_delivery`. It is referenced more than once, so
 * PostgreSQL materialises it into a tuplestore, and a tuplestore carries no
 * index: a correlated subquery against it scans the whole set once per row.
 * Issue #410 measured the fixture-level completeness fields costing 845.5 ms of
 * an 889.5 ms plan that way â€” 51 scans for the event count and 102 for the
 * empty-innings test, about 1.24 million tuple scans to produce 51 integers and
 * 51 arrays. Both are now one grouped pass over the same set, which is why
 * `innings_event_count` exists rather than the two subqueries it replaces. The
 * plan captures are in `evidence/validation/issue-410-*`.
 *
 * `innings_event_count` reads `accepted_delivery`, which `standardInningsPredicate`
 * has already restricted to standard innings, so it inherits the super-over
 * boundary rather than restating it. It carries no `innings` alias of its own and
 * must not acquire one: a second spelling of the exclusion is what
 * `super-over-scope.ts` exists to prevent.
 */
export async function listParticipantFixtures(
  options: ParticipantFixtureListOptions,
  executor: QueryExecutor = getDatabasePool(),
): Promise<ParticipantFixturePage> {
  const values: unknown[] = [options.participantId];
  const conditions: string[] = ['fs.person_id = $1::bigint'];

  if (options.after) {
    values.push(options.after.startDate);
    const dateParameter = values.length;
    values.push(options.after.fixtureId);
    const idParameter = values.length;
    conditions.push(
      `(f.start_date, f.fixture_id) < ($${dateParameter}::date, $${idParameter}::bigint)`,
    );
  }

  values.push(options.limit + 1);
  const limitParameter = values.length;

  const result = await executeQuery<ParticipantFixtureRecord>(
    executor,
    `
      WITH selected_fixture AS (
        SELECT
          f.fixture_id,
          f.competition_id,
          f.balls_per_over,
          f.scheduled_overs,
          f.missing_fields,
          f.season,
          f.match_type,
          f.team_type,
          f.gender,
          f.start_date,
          f.end_date,
          fs.team_id,
          fs.role
        FROM fixture_squad fs
        INNER JOIN fixture f
          ON f.fixture_id = fs.fixture_id
        INNER JOIN submission publication
          ON publication.submission_id = f.first_seen_in
         AND publication.status = 'accepted'
        WHERE ${conditions.join(' AND ')}
        ORDER BY f.start_date DESC, f.fixture_id DESC
        LIMIT $${limitParameter}
      ),
      accepted_delivery AS (
        SELECT d.*,
          i.fixture_id
        FROM delivery_current d
        JOIN innings i
          ON i.innings_id = d.innings_id
         AND ${standardInningsPredicate('i')}
        JOIN submission source_submission
          ON source_submission.submission_id = d.submission_id
         AND source_submission.status = 'accepted'
        WHERE i.fixture_id IN (SELECT fixture_id FROM selected_fixture)
      ),
      batting AS (
        SELECT
          d.fixture_id,
          SUM(d.runs_off_bat)::int AS runs_scored,
          COUNT(*) FILTER (WHERE ${countsAsBallFacedSql('d')})::int AS balls_faced,
          COUNT(*) FILTER (WHERE d.runs_off_bat = 4 AND NOT d.non_boundary)::int AS fours,
          COUNT(*) FILTER (WHERE d.runs_off_bat = 6 AND NOT d.non_boundary)::int AS sixes
        FROM accepted_delivery d
        WHERE d.striker_id = $1::bigint
        GROUP BY d.fixture_id
      ),
      bowling AS (
        SELECT
          d.fixture_id,
          SUM(
            d.runs_off_bat + ${bowlerChargedExtrasSql('d')}
          )::int AS runs_conceded,
          COALESCE(SUM(${bowlerWideRunsSql('d')}), 0)::int AS wides,
          COALESCE(SUM(d.extra_noballs), 0)::int AS no_balls,
          COUNT(*) FILTER (
            WHERE ${isLegalDeliverySql('d')}
          )::int AS legal_balls_bowled,
          COALESCE(SUM((
            SELECT COUNT(*)
            FROM delivery_wicket dw
            JOIN dismissal_kind dk ON dk.code = dw.kind
            WHERE dw.delivery_id = d.delivery_id
              AND dk.credits_bowler = true
          )), 0)::int AS wickets_taken
        FROM accepted_delivery d
        WHERE d.bowler_id = $1::bigint
        GROUP BY d.fixture_id
      ),
      innings_event_count AS (
        SELECT
          d.innings_id,
          COUNT(*)::int AS accepted_event_count
        FROM accepted_delivery d
        GROUP BY d.innings_id
      ),
      fixture_state AS (
        SELECT
          sf.fixture_id,
          COUNT(i.innings_id)::int AS standard_innings_count,
          COALESCE(SUM(iec.accepted_event_count), 0)::int AS accepted_event_count,
          COALESCE(
            ARRAY_AGG(i.innings_id::text ORDER BY i.ordinal) FILTER (
              WHERE i.innings_id IS NOT NULL
                AND iec.innings_id IS NULL
            ),
            ARRAY[]::text[]
          ) AS empty_standard_innings_ids
        FROM selected_fixture sf
        LEFT JOIN innings i
          ON i.fixture_id = sf.fixture_id
         AND ${standardInningsPredicate('i')}
        LEFT JOIN innings_event_count iec
          ON iec.innings_id = i.innings_id
        GROUP BY sf.fixture_id
      )
      SELECT
        sf.fixture_id::text AS "fixtureId",
        sf.competition_id::text AS "competitionId",
        c.name AS "competitionName",
        sf.balls_per_over AS "ballsPerOver",
        sf.scheduled_overs AS "scheduledOvers",
        sf.season AS "season",
        sf.match_type AS "matchType",
        sf.team_type AS "teamType",
        sf.gender AS "gender",
        to_char(sf.start_date, 'YYYY-MM-DD') AS "startDate",
        to_char(sf.end_date, 'YYYY-MM-DD') AS "endDate",
        sf.team_id::text AS "teamId",
        t.name AS "teamName",
        sf.role AS "role",
        sf.missing_fields AS "missingFields",
        state.standard_innings_count AS "standardInningsCount",
        state.accepted_event_count AS "acceptedEventCount",
        state.empty_standard_innings_ids AS "emptyStandardInningsIds",
        b.runs_scored AS "runsScored",
        b.balls_faced AS "ballsFaced",
        b.fours AS "fours",
        b.sixes AS "sixes",
        w.runs_conceded AS "runsConceded",
        w.wides AS wides,
        w.no_balls AS "noBalls",
        w.legal_balls_bowled AS "legalBallsBowled",
        w.wickets_taken AS "wicketsTaken"
      FROM selected_fixture sf
      INNER JOIN team t
        ON t.team_id = sf.team_id
      LEFT JOIN competition c
        ON c.competition_id = sf.competition_id
      LEFT JOIN batting b
        ON b.fixture_id = sf.fixture_id
      LEFT JOIN bowling w
        ON w.fixture_id = sf.fixture_id
      INNER JOIN fixture_state state
        ON state.fixture_id = sf.fixture_id
      ORDER BY sf.start_date DESC, sf.fixture_id DESC
    `,
    values,
  );

  return {
    records: result.rows.slice(0, options.limit),
    hasMore: result.rows.length > options.limit,
  };
}

export interface FixtureCompetitorRecord {
  fixtureId: string;
  competitorId: string;
  name: string;
  ordinal: number;
}

/**
 * The competitors contesting each of the given fixtures.
 *
 * Fetched for a whole page in one statement rather than per fixture, because at
 * roughly 173 ms per round trip a query per fixture would dominate the response.
 */
export async function listCompetitorsForFixtures(
  fixtureIds: string[],
  executor: QueryExecutor = getDatabasePool(),
): Promise<FixtureCompetitorRecord[]> {
  if (fixtureIds.length === 0) {
    return [];
  }

  const result = await executeQuery<FixtureCompetitorRecord>(
    executor,
    `
      SELECT
        ft.fixture_id::text AS "fixtureId",
        t.team_id::text AS "competitorId",
        t.name AS "name",
        ft.ordinal AS "ordinal"
      FROM fixture_team ft
      INNER JOIN team t
        ON t.team_id = ft.team_id
      WHERE ft.fixture_id = ANY($1::bigint[])
      ORDER BY ft.fixture_id ASC, ft.ordinal ASC
    `,
    [fixtureIds],
  );

  return result.rows;
}
===== SNAPSHOT =====
import type { Pool, PoolClient } from 'pg';

import { executeQuery, getDatabasePool, type QueryExecutor } from '../../database';
import type {
  ParticipantAggregateRow,
  ParticipantAggregatesSource,
} from './participant-aggregates.model';
import {
  loadParticipantAggregatesSource,
  participantAggregatesDefinitionVersion,
} from './participant-aggregates.repository';

/**
 * Stored participant aggregate rows (issue #592).
 *
 * Delivery rows remain the source of truth. A participant's stored rows are
 * served only while their snapshot state was built from the participant's
 * current `participant_statistics_version` under the running definition
 * version; in every other case the aggregates are derived live.
 *
 * Refresh is selective: a change recomputes each affected participant's query
 * once and rewrites only the affected scope rows; unaffected participants are
 * not recomputed and their rows stay byte-identical. Within one participant the
 * whole query runs once; a scope row whose figures did not change is left
 * untouched.
 */

interface ParticipantAggregateSnapshotRead {
  participantId: string;
  participantName: string;
  /**
   * The participant's current statistics data version, read before any live
   * derivation. Null when no tracked write has affected the participant, in
   * which case stored rows are never served or written.
   */
  dataVersion: number | null;
  /** The stored rows when they are current; otherwise null. */
  rows: ParticipantAggregateRow[] | null;
}

/**
 * - `refreshed`: the state row and every changed scope row were written.
 * - `current`: the stored rows were already current; nothing was written.
 * - `stale`: the participant's version moved after it was read; nothing was written.
 * - `busy`: another refresh holds the lease, or a row lock was not immediately
 *   available; nothing was written.
 * - `untracked`: the participant has no statistics version; nothing was written.
 */
type ParticipantAggregateSnapshotWrite = 'refreshed' | 'current' | 'stale' | 'busy' | 'untracked';

export interface ParticipantAggregateSnapshotStore {
  /** Returns null when the participant does not exist. */
  read(participantId: string): Promise<ParticipantAggregateSnapshotRead | null>;
  /**
   * Stores rows derived after `dataVersion` was read. Never waits for a lock:
   * when the lease or a row lock is held elsewhere it writes nothing.
   */
  write(
    participantId: string,
    dataVersion: number,
    rows: readonly ParticipantAggregateRow[],
  ): Promise<ParticipantAggregateSnapshotWrite>;
  /** Records a failed refresh attempt. Best effort: it never throws. */
  recordFailure(participantId: string, error: unknown): Promise<void>;
}

const lockNotAvailable = '55P03';
const maximumErrorLength = 500;

/** The scope key of a grouped row: its level, and its competition and season where grouped. */
export function participantAggregateScopeKey(row: ParticipantAggregateRow): string {
  const competition = row.competitionId ?? 'none';
  if (row.seasonGrouped) {
    return `season:${competition}:${row.season ?? ''}`;
  }
  return row.competitionGrouped ? `competition:${competition}` : 'career';
}

function isLockNotAvailable(error: unknown): boolean {
  const code =
    (error as { code?: unknown; cause?: { code?: unknown } } | null)?.code ??
    (error as { cause?: { code?: unknown } } | null)?.cause?.code;
  return code === lockNotAvailable;
}

async function inTransaction<T>(
  pool: Pool,
  operation: (client: PoolClient) => Promise<T>,
): Promise<T> {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    // Any implicit row lock that is not free at once aborts the refresh rather
    // than delaying the read that triggered it.
    await client.query(`SET LOCAL lock_timeout = '1ms'`);
    const result = await operation(client);
    await client.query('COMMIT');
    return result;
  } catch (error) {
    await client.query('ROLLBACK').catch(() => undefined);
    throw error;
  } finally {
    client.release();
  }
}

/** Takes the participant's refresh lease for this transaction, without waiting. */
async function tryTakeLease(client: PoolClient, participantId: string): Promise<boolean> {
  const result = await client.query<{ acquired: boolean }>(
    `SELECT pg_try_advisory_xact_lock(
       hashtextextended('participant-aggregate-snapshot:' || $1::bigint::text, 0)
     ) AS acquired`,
    [participantId],
  );
  return result.rows[0]?.acquired === true;
}

/** Ends the transaction without writing and reports why. */
class NoWrite extends Error {
  constructor(readonly outcome: Exclude<ParticipantAggregateSnapshotWrite, 'refreshed'>) {
    super(outcome);
  }
}

export function createParticipantAggregateSnapshotStore(
  pool?: Pool,
): ParticipantAggregateSnapshotStore {
  const database = () => pool ?? getDatabasePool();

  return {
    async read(participantId) {
      const result = await executeQuery<{
        participantId: string;
        participantName: string;
        dataVersion: string | null;
        rows: ParticipantAggregateRow[] | null;
      }>(
        database(),
        `
          SELECT
            person.person_id::text AS "participantId",
            person.display_name AS "participantName",
            version.data_version::text AS "dataVersion",
            CASE
              WHEN state.data_version = version.data_version
               AND state.definition_version = $2
              THEN (
                SELECT COALESCE(
                  jsonb_agg(
                    snapshot.payload
                    ORDER BY
                      (snapshot.payload->>'competitionGrouped')::boolean DESC,
                      (snapshot.payload->>'seasonGrouped')::boolean DESC,
                      (snapshot.payload->>'competitionId')::bigint ASC NULLS LAST,
                      snapshot.payload->>'season' ASC
                  ),
                  '[]'::jsonb
                )
                FROM participant_aggregate_snapshot snapshot
                WHERE snapshot.participant_id = person.person_id
              )
            END AS rows
          FROM person
          LEFT JOIN participant_statistics_version version
            ON version.participant_id = person.person_id
          LEFT JOIN participant_aggregate_snapshot_state state
            ON state.participant_id = person.person_id
          WHERE person.person_id = $1::bigint
        `,
        [participantId, participantAggregatesDefinitionVersion],
      );
      const row = result.rows[0];
      if (!row) {
        return null;
      }

      return {
        participantId: row.participantId,
        participantName: row.participantName,
        dataVersion: row.dataVersion === null ? null : Number(row.dataVersion),
        rows: row.dataVersion === null ? null : row.rows,
      };
    },

    async write(participantId, dataVersion, rows) {
      try {
        return await inTransaction(database(), async (client) => {
          if (!(await tryTakeLease(client, participantId))) {
            throw new NoWrite('busy');
          }

          // Holding a share lock on the version row until commit means the rows
          // cannot be stored against a version a concurrent write has advanced.
          const version = await client.query<{ dataVersion: string }>(
            `SELECT data_version::text AS "dataVersion"
             FROM participant_statistics_version
             WHERE participant_id = $1::bigint
             FOR SHARE NOWAIT`,
            [participantId],
          );
          const currentVersion = version.rows[0]?.dataVersion;
          if (currentVersion === undefined) {
            throw new NoWrite('untracked');
          }
          if (Number(currentVersion) !== dataVersion) {
            throw new NoWrite('stale');
          }

          const state = await client.query<{ current: boolean }>(
            `SELECT (data_version = $2 AND definition_version = $3) AS current
             FROM participant_aggregate_snapshot_state
             WHERE participant_id = $1::bigint
             FOR UPDATE NOWAIT`,
            [participantId, dataVersion, participantAggregatesDefinitionVersion],
          );
          if (state.rows[0]?.current === true) {
            throw new NoWrite('current');
          }

          await client.query(
            `INSERT INTO participant_aggregate_snapshot_state (
               participant_id, data_version, definition_version, refresh_count, refreshed_at,
               attempt_count, last_error
             )
             VALUES ($1::bigint, $2, $3, 1, now(), 0, NULL)
             ON CONFLICT (participant_id) DO UPDATE
             SET data_version = EXCLUDED.data_version,
                 definition_version = EXCLUDED.definition_version,
                 refresh_count = participant_aggregate_snapshot_state.refresh_count + 1,
                 refreshed_at = now(),
                 attempt_count = 0,
                 last_error = NULL`,
            [participantId, dataVersion, participantAggregatesDefinitionVersion],
          );

          const scopeRows = rows.map((row) => ({
            key: participantAggregateScopeKey(row),
            payload: row,
          }));
          await client.query(
            `DELETE FROM participant_aggregate_snapshot
             WHERE participant_id = $1::bigint
               AND NOT (scope_key = ANY($2::text[]))`,
            [participantId, scopeRows.map((row) => row.key)],
          );
          // A row whose figures did not change is not rewritten, so its bytes,
          // versions and refresh count stay exactly as they were.
          await client.query(
            `INSERT INTO participant_aggregate_snapshot AS snapshot (
               participant_id, scope_key, payload, data_version, definition_version
             )
             SELECT $1::bigint, source.key, source.payload, $2, $3
             FROM jsonb_to_recordset($4::jsonb) AS source(key text, payload jsonb)
             ON CONFLICT (participant_id, scope_key) DO UPDATE
             SET payload = EXCLUDED.payload,
                 data_version = EXCLUDED.data_version,
                 definition_version = EXCLUDED.definition_version,
                 refresh_count = snapshot.refresh_count + 1,
                 refreshed_at = now()
             WHERE snapshot.payload IS DISTINCT FROM EXCLUDED.payload`,
            [
              participantId,
              dataVersion,
              participantAggregatesDefinitionVersion,
              JSON.stringify(scopeRows),
            ],
          );

          return 'refreshed' as const;
        });
      } catch (error) {
        if (error instanceof NoWrite) {
          return error.outcome;
        }
        if (isLockNotAvailable(error)) {
          return 'busy';
        }
        throw error;
      }
    },

    async recordFailure(participantId, error) {
      const message = (error instanceof Error ? error.message : String(error)).slice(
        0,
        maximumErrorLength,
      );
      try {
        await inTransaction(database(), async (client) => {
          if (!(await tryTakeLease(client, participantId))) {
            return;
          }
          await client.query(
            `INSERT INTO participant_aggregate_snapshot_state (participant_id, attempt_count, last_error)
             VALUES ($1::bigint, 1, $2)
             ON CONFLICT (participant_id) DO UPDATE
             SET attempt_count = participant_aggregate_snapshot_state.attempt_count + 1,
                 last_error = EXCLUDED.last_error`,
            [participantId, message],
          );
        });
      } catch {
        // Recording an attempt must never turn a failed refresh into a failed read.
      }
    },
  };
}

export type ParticipantAggregateRefreshOutcome =
  ParticipantAggregateSnapshotWrite | 'absent' | 'failed';

export interface RefreshParticipantAggregateSnapshotsOptions {
  store?: ParticipantAggregateSnapshotStore;
  loadSource?: (participantId: string) => Promise<ParticipantAggregatesSource | null>;
}

/**
 * Refreshes the stored rows of each listed participant whose rows are not
 * current. A participant whose rows are current is not recomputed. A failure
 * for one participant is recorded and does not stop the others; running the
 * refresh again retries it.
 */
export async function refreshParticipantAggregateSnapshots(
  participantIds: readonly string[],
  options: RefreshParticipantAggregateSnapshotsOptions = {},
): Promise<Map<string, ParticipantAggregateRefreshOutcome>> {
  const store = options.store ?? createParticipantAggregateSnapshotStore();
  const loadSource = options.loadSource ?? loadParticipantAggregatesSource;
  const outcomes = new Map<string, ParticipantAggregateRefreshOutcome>();

  for (const participantId of participantIds) {
    try {
      const snapshot = await store.read(participantId);
      if (!snapshot) {
        outcomes.set(participantId, 'absent');
      } else if (snapshot.dataVersion === null) {
        outcomes.set(participantId, 'untracked');
      } else if (snapshot.rows !== null) {
        outcomes.set(participantId, 'current');
      } else {
        const source = await loadSource(participantId);
        outcomes.set(
          participantId,
          source ? await store.write(participantId, snapshot.dataVersion, source.rows) : 'absent',
        );
      }
    } catch (error) {
      await store.recordFailure(participantId, error);
      outcomes.set(participantId, 'failed');
    }
  }

  return outcomes;
}

/**
 * Deletes every stored participant aggregate snapshot. Any write to aggregate
 * inputs that does not advance participant statistics versions (a
 * data-rewriting migration, a seed that bypasses ingest, a manual repair) must
 * call this, or run `SELECT invalidate_participant_aggregate_snapshots()`, in
 * the same transaction.
 */
export async function invalidateParticipantAggregateSnapshots(
  executor: QueryExecutor,
): Promise<number> {
  const result = await executeQuery<{ invalidated: string }>(
    executor,
    'SELECT invalidate_participant_aggregate_snapshots()::text AS invalidated',
  );
  return Number(result.rows[0]?.invalidated ?? 0);
}
