    const { repository } = repositoryWithQuery();
    const methods: Array<keyof BatchRepository> = [
      'createBatch',
      'createOrFindBatchAndQueueValidation',
      'listBatches',
      'insertBatchItems',
      'applyReviewDecision',
      'publishAcceptedItems',
    ];
    expect(methods.every((method) => typeof repository[method] === 'function')).toBe(true);
  });
});

