  const result = await executeQuery<{ authorized: boolean }>(
    client,
    `
      SELECT EXISTS (
        SELECT 1
        FROM app_user account
        JOIN fixture
          ON fixture.fixture_id = $2
        WHERE account.app_user_id = $1
          AND account.application_role IN ('submitter', 'admin')
          AND account.disabled_at IS NULL
          AND (
