function mapAdministratorUser(row: AdministratorUserRow): AdministratorManagedUserWithAuthSubject {
  if (!isApplicationRole(row.role)) {
    throw new Error('Managed application account has an unsupported role');
  }

  if (!isSubmitterApprovalState(row.approvalState)) {
    throw new Error('Managed application account has an unsupported approval state');
  }

  if (row.competitionIds.length !== row.competitionNames.length) {
    throw new Error('Managed application account has inconsistent competition scope data');
  }

  if ((row.requestedCompetitionId === null) !== (row.requestedCompetitionName === null)) {
    throw new Error('Managed application account has inconsistent requested competition data');
  }

  return {
    id: row.id,
    authSubject: row.authSubject,
    displayName: row.displayName,
    role: row.role,
    approvalState: row.approvalState,
    requestedCompetition:
      row.requestedCompetitionId && row.requestedCompetitionName
        ? {
            competitionId: row.requestedCompetitionId,
            name: row.requestedCompetitionName,
          }
        : null,
    competitionScopes: row.competitionIds.map((competitionId, index) => ({
      competitionId,
      name: row.competitionNames[index]!,
    })),
    disabled: row.disabledAt !== null,
    updatedAt: row.updatedAt.toISOString(),
    submitterAccessUpdatedAt: row.submitterAccessUpdatedAt?.toISOString() ?? null,
    submitterAccessUpdatedBy: row.submitterAccessUpdatedById
      ? {
          id: row.submitterAccessUpdatedById,
          displayName: row.submitterAccessUpdatedByDisplayName,
        }
      : null,
    previouslyRevoked: row.previouslyRevoked,
  };
}

async function listUsers(
  executor: QueryExecutor,
): Promise<AdministratorManagedUserWithAuthSubject[]> {
  const result = await executeQuery<AdministratorUserRow>(
    executor,
    `${administratorUserSelect}
      WHERE managed.deletion_state = 'active'
      GROUP BY
        managed.app_user_id,
        requested_competition.competition_id,
        access_administrator.app_user_id
      ORDER BY
        CASE managed.submitter_approval_state WHEN 'pending' THEN 0 ELSE 1 END,
        lower(COALESCE(managed.display_name, '')),
        managed.app_user_id
    `,
  );

  return result.rows.map(mapAdministratorUser);
}

async function findUserById(
  accountId: string,
  executor: QueryExecutor,
): Promise<AdministratorManagedUserWithAuthSubject> {
  const result = await executeQuery<AdministratorUserRow>(
    executor,
    `${administratorUserSelect}
      WHERE managed.app_user_id = $1
        AND managed.deletion_state = 'active'
      GROUP BY
        managed.app_user_id,
        requested_competition.competition_id,
        access_administrator.app_user_id
    `,
    [accountId],
  );

  const account = result.rows[0];

  if (!account) {
    throw new AdminUserNotFoundError();
  }

  return mapAdministratorUser(account);
}

async function listCompetitionScopes(
  executor: QueryExecutor,
): Promise<AdministratorCompetitionScope[]> {
  const result = await executeQuery<AdministratorCompetitionScope>(
    executor,
    `
      SELECT
        competition_id::text AS "competitionId",
        name
      FROM competition
      ORDER BY name, competition_id
    `,
  );

  return result.rows;
}

async function applySubmitterAccessTransition(
  pool: Pool,
  targetAccountId: string,
  administratorAccountId: string,
  action: SubmitterAccessAction,
  competitionIds: string[],
): Promise<AdministratorManagedUserWithAuthSubject> {
  return withTransaction(pool, async (client) => {
    const targetResult = await executeQuery<TargetAccountRow>(
      client,
      `
        SELECT
          account.application_role AS role,
          account.submitter_approval_state AS "approvalState",
          account.submitter_requested_competition_id::text AS "requestedCompetitionId",
          CASE
            WHEN account.submitter_requested_competition_id IS NULL THEN false
            ELSE EXISTS (
              SELECT 1
              FROM submitter_competition_scope requested_scope
              WHERE requested_scope.app_user_id = account.app_user_id
                AND requested_scope.competition_id = account.submitter_requested_competition_id
            )
          END AS "requestedCompetitionAlreadyGranted",
          account.disabled_at AS "disabledAt"
        FROM app_user account
        WHERE account.app_user_id = $1
        FOR UPDATE
      `,
      [targetAccountId],
    );
    const target = targetResult.rows[0];

    if (!target) {
      throw new AdminUserNotFoundError();
    }

    if (!isApplicationRole(target.role)) {
      throw new Error('Managed application account has an unsupported role');
    }

    if (!isSubmitterApprovalState(target.approvalState)) {
      throw new Error('Managed application account has an unsupported approval state');
    }

    if (target.role === 'admin') {
      throw new AdminManagementConflictError(
        'ADMIN_ACCOUNT_NOT_MANAGEABLE',
        'Administrator accounts cannot be changed through submitter access management.',
      );
    }

    if (target.disabledAt) {
      throw new AdminManagementConflictError(
        'DISABLED_ACCOUNT_NOT_MANAGEABLE',
        'Disabled accounts cannot be changed through submitter access management.',
      );
    }

    const hasPendingAdditionalScopeRequest =
      target.role === 'submitter' &&
      target.approvalState === 'approved' &&
      target.requestedCompetitionId !== null &&
      !target.requestedCompetitionAlreadyGranted;
    const transition = resolveSubmitterAccessTransition(
      {
        role: target.role,
        approvalState: target.approvalState,
        hasPendingAdditionalScopeRequest,
      },
      action,
    );
    const grantsAccess = transition === 'approve' || transition === 'scope';
    let requestedCompetitionIds = [...new Set(competitionIds)];

    if (transition === 'approve') {
      if (!target.requestedCompetitionId) {
        throw new AdminManagementConflictError(
          'REQUESTED_COMPETITION_SCOPE_MISSING',
          'The pending request does not identify a competition and cannot be approved.',
        );
      }

      if (
        requestedCompetitionIds.length !== 1 ||
        requestedCompetitionIds[0] !== target.requestedCompetitionId
      ) {
        throw new AdminManagementConflictError(
          'REQUESTED_COMPETITION_SCOPE_MISMATCH',
          'Approval must grant the competition stored on the pending request.',
        );
      }

      requestedCompetitionIds = [target.requestedCompetitionId];
    }

    if (
      transition === 'scope' &&
      hasPendingAdditionalScopeRequest &&
      target.requestedCompetitionId &&
      !requestedCompetitionIds.includes(target.requestedCompetitionId)
    ) {
      throw new AdminManagementConflictError(
        'REQUESTED_COMPETITION_SCOPE_MISMATCH',
        'Approving the additional scope request must include the requested competition.',
      );
    }

    if (grantsAccess && requestedCompetitionIds.length === 0) {
      throw new InvalidCompetitionScopesError([]);
    }

    if (grantsAccess) {
      const validScopes = await executeQuery<{ competitionId: string }>(
        client,
        `
          SELECT competition_id::text AS "competitionId"
          FROM competition
          WHERE competition_id = ANY($1::bigint[])
        `,
        [requestedCompetitionIds],
      );
      const validIds = new Set(validScopes.rows.map((scope) => scope.competitionId));
      const invalidIds = requestedCompetitionIds.filter(
        (competitionId) => !validIds.has(competitionId),
      );

      if (invalidIds.length > 0) {
        throw new InvalidCompetitionScopesError(invalidIds);
      }
    }

    await executeQuery(
      client,
      `
        UPDATE app_user
        SET
          application_role = $2,
          submitter_approval_state = $3,
          submitter_requested_competition_id = NULL,
          submitter_access_updated_at = now(),
          submitter_access_updated_by = $4
        WHERE app_user_id = $1
      `,
      [
        targetAccountId,
        transition === 'reject_scope' || grantsAccess ? 'submitter' : 'viewer',
        transition === 'reject' ? 'rejected' : 'approved',
        administratorAccountId,
      ],
    );

    if (
      transition === 'approve' ||
      transition === 'reject' ||
      transition === 'reject_scope' ||
      (transition === 'scope' && hasPendingAdditionalScopeRequest) ||
      transition === 'revoke'
    ) {
      await executeQuery(
        client,
        `
          INSERT INTO submitter_access_history (
            app_user_id, action, competition_id, administrator_app_user_id
          )
          VALUES ($1, $2, $3, $4)
        `,
        [
          targetAccountId,
          transition === 'approve' || (transition === 'scope' && hasPendingAdditionalScopeRequest)
            ? 'approved'
            : transition === 'reject' || transition === 'reject_scope'
              ? 'rejected'
              : 'revoked',
          target.requestedCompetitionId,
          administratorAccountId,
        ],
      );
    }

    if (transition !== 'reject_scope') {
      await executeQuery(client, 'DELETE FROM submitter_competition_scope WHERE app_user_id = $1', [
        targetAccountId,
      ]);

      if (grantsAccess) {
        await executeQuery(
          client,
          `
            INSERT INTO submitter_competition_scope (app_user_id, competition_id)
            SELECT $1, requested.competition_id
            FROM unnest($2::bigint[]) AS requested(competition_id)
          `,
          [targetAccountId, requestedCompetitionIds],
        );
      }
    }

    return findUserById(targetAccountId, client);
  });
}

export function createAdminRepository(pool: Pool = getDatabasePool()): AdminRepository {
  return {
    async listUserManagementData() {
      const [users, availableScopes] = await Promise.all([
        listUsers(pool),
        listCompetitionScopes(pool),
      ]);

      return { users, availableScopes };
    },

    async updateSubmitterAccess(targetAccountId, administratorAccountId, update) {
      return applySubmitterAccessTransition(
        pool,
        targetAccountId,
        administratorAccountId,
        update.approved ? 'grant' : 'revoke',
        update.competitionIds,
      );
    },

    async rejectSubmitterAccessRequest(targetAccountId, administratorAccountId) {
      return applySubmitterAccessTransition(
        pool,
        targetAccountId,
        administratorAccountId,
        'reject',
        [],
      );
    },
    async updateRole(targetAccountId, administratorAccountId, update) {
      return withTransaction(pool, async (client) => {
        const targetResult = await executeQuery<TargetAccountRow>(
          client,
          `
            SELECT application_role AS role, submitter_approval_state AS "approvalState",
              submitter_requested_competition_id::text AS "requestedCompetitionId",
              false AS "requestedCompetitionAlreadyGranted", disabled_at AS "disabledAt"
            FROM app_user WHERE app_user_id = $1 FOR UPDATE
          `,
          [targetAccountId],
        );
        const target = targetResult.rows[0];
        if (!target) throw new AdminUserNotFoundError();
        if (target.disabledAt) {
          throw new AdminManagementConflictError(
            'DISABLED_ACCOUNT_NOT_MANAGEABLE',
            'Disabled accounts cannot be changed through role management.',
          );
        }
        if (target.role === 'admin') {
          throw new AdminManagementConflictError(
            'ADMIN_ACCOUNT_NOT_MANAGEABLE',
            'Administrator accounts cannot be changed through role management.',
          );
        }
        if (update.role !== 'admin') {
          throw new AdminManagementConflictError(
            'ROLE_TRANSITION_MANAGED_BY_SUBMITTER_ACCESS',
            'Viewer and submitter transitions must use the submitter access management endpoints.',
          );
        }
        await executeQuery(
          client,
          `UPDATE app_user SET application_role = 'admin', submitter_access_updated_at = now(), submitter_access_updated_by = $2 WHERE app_user_id = $1`,
          [targetAccountId, administratorAccountId],
        );
        return findUserById(targetAccountId, client);
      });
    },
  };
}
===== API ACCESS =====
import type {
  ApiAccessDecision,
  ApiAccessRequest,
  ApiAccessRequestCreate,
  ApiConsumer,
} from '@sport-analytics/contracts';
import type { Pool } from 'pg';

import { executeQuery, getDatabasePool, withTransaction, type QueryExecutor } from '../../database';

interface RequestRow {
  id: string;
  requesterAccountId: string;
  name: string;
  intendedUse: string;
  state: 'pending' | 'approved' | 'rejected';
  createdAt: Date;
  reviewedAt: Date | null;
  reviewedById: string | null;
  reviewedByName: string | null;
  consumerId: string | null;
  requesterAuthSubject?: string;
  requesterDisplayName?: string | null;
}

type PendingApiAccessRequestRecord = ApiAccessRequest & {
  requesterAuthSubject: string;
  requesterDisplayName: string | null;
};

const requestSelect = `SELECT request.api_consumer_access_request_id::text AS id,
  request.requester_app_user_id::text AS "requesterAccountId", request.consumer_name AS name,
  request.intended_use AS "intendedUse", request.request_state AS state,
  request.created_at AS "createdAt", request.reviewed_at AS "reviewedAt",
  request.review_reason AS "reviewReason",
  reviewer.app_user_id::text AS "reviewedById", reviewer.display_name AS "reviewedByName",
  requester.auth_subject AS "requesterAuthSubject",
  requester.display_name AS "requesterDisplayName",
  request.api_consumer_id::text AS "consumerId"
 FROM api_consumer_access_request request
 JOIN app_user requester ON requester.app_user_id = request.requester_app_user_id
 LEFT JOIN app_user reviewer ON reviewer.app_user_id = request.reviewed_by_app_user_id`;

function mapRequest(row: RequestRow & { reviewReason?: string | null }): ApiAccessRequest {
  return {
    id: row.id,
    requesterAccountId: row.requesterAccountId,
    name: row.name,
    intendedUse: row.intendedUse,
    state: row.state,
    createdAt: row.createdAt.toISOString(),
    reviewedAt: row.reviewedAt?.toISOString() ?? null,
    reviewedBy: row.reviewedById ? { id: row.reviewedById, displayName: row.reviewedByName } : null,
    reviewReason: row.reviewReason ?? null,
  };
}

async function readRequest(executor: QueryExecutor, id: string): Promise<ApiAccessRequest> {
  const result = await executeQuery<RequestRow & { reviewReason: string | null }>(
    executor,
    `${requestSelect} WHERE request.api_consumer_access_request_id = $1`,
    [id],
  );
  if (!result.rows[0]) throw new ApiAccessRequestNotFoundError();
  return mapRequest(result.rows[0]);
}

async function readConsumer(executor: QueryExecutor, id: string): Promise<ApiConsumer> {
  const result = await executeQuery<{
    id: string;
    name: string;
    rateLimitPerMinute: number;
    dailyQuota: number;
    createdAt: Date;
  }>(
    executor,
    `SELECT api_consumer_id::text AS id, name,
    rate_limit_per_minute AS "rateLimitPerMinute", daily_quota AS "dailyQuota", created_at AS "createdAt"
    FROM api_consumer WHERE api_consumer_id = $1`,
    [id],
  );
  const row = result.rows[0];
  if (!row) throw new ApiAccessRequestNotFoundError();
  const keys = await executeQuery<{
    id: string;
    prefix: string;
    createdAt: Date;
    revokedAt: Date | null;
  }>(
    executor,
    `SELECT api_consumer_key_id::text AS id, key_prefix AS prefix, created_at AS "createdAt",
      revoked_at AS "revokedAt" FROM api_consumer_key WHERE api_consumer_id = $1 ORDER BY api_consumer_key_id`,
    [id],
  );
  return {
    ...row,
    createdAt: row.createdAt.toISOString(),
    keys: keys.rows.map((key) => ({
      ...key,
      createdAt: key.createdAt.toISOString(),
      revokedAt: key.revokedAt?.toISOString() ?? null,
    })),
  };
}

export interface ApiAccessRepository {
  createRequest(accountId: string, input: ApiAccessRequestCreate): Promise<ApiAccessRequest>;
  getOwn(
    accountId: string,
  ): Promise<{ request: ApiAccessRequest | null; consumer: ApiConsumer | null }>;
  listPending(): Promise<PendingApiAccessRequestRecord[]>;
  decide(adminId: string, requestId: string, input: ApiAccessDecision): Promise<ApiAccessRequest>;
  listConsumers(): Promise<ApiConsumer[]>;
  updateLimits(
    consumerId: string,
    rateLimitPerMinute: number,
    dailyQuota: number,
  ): Promise<ApiConsumer>;
  revokeAnyKey(consumerId: string, keyId: string): Promise<void>;
}

export function createApiAccessRepository(pool: Pool = getDatabasePool()): ApiAccessRepository {
  return {
    async createRequest(accountId, input) {
      try {
        return await withTransaction(pool, async (client) => {
          await executeQuery(client, `SELECT pg_advisory_xact_lock($1::bigint)`, [accountId]);
          const existing = await executeQuery(
            client,
            `SELECT 1 FROM api_consumer_access_request
             WHERE requester_app_user_id = $1 AND request_state IN ('pending', 'approved') LIMIT 1`,
            [accountId],
          );
          if (existing.rows[0]) throw new ApiAccessConflictError();
          const inserted = await executeQuery<{ id: string }>(
            client,
            `INSERT INTO api_consumer_access_request (requester_app_user_id, consumer_name, intended_use)
             VALUES ($1, $2, $3) RETURNING api_consumer_access_request_id::text AS id`,
            [accountId, input.name, input.intendedUse],
          );
          return readRequest(client, inserted.rows[0]!.id);
        });
      } catch (error: unknown) {
        if (error instanceof ApiAccessConflictError) throw error;
        if ((error as { code?: string }).code === '23505') throw new ApiAccessConflictError();
        throw error;
      }
    },
    async getOwn(accountId) {
      const result = await executeQuery<RequestRow & { reviewReason: string | null }>(
        pool,
        `${requestSelect} WHERE request.requester_app_user_id = $1
         ORDER BY request.api_consumer_access_request_id DESC LIMIT 1`,
        [accountId],
      );
      const row = result.rows[0];
      return {
        request: row ? mapRequest(row) : null,
        consumer: row?.consumerId ? await readConsumer(pool, row.consumerId) : null,
      };
    },
    async listPending() {
      const result = await executeQuery<RequestRow & { reviewReason: string | null }>(
        pool,
        `${requestSelect} WHERE request.request_state = 'pending'
         ORDER BY request.created_at, request.api_consumer_access_request_id`,
      );
      return result.rows.map((row) => ({
        ...mapRequest(row),
        requesterAuthSubject: row.requesterAuthSubject!,
        requesterDisplayName: row.requesterDisplayName ?? null,
      }));
    },
    async decide(adminId, requestId, input) {
      return withTransaction(pool, async (client) => {
        const locked = await executeQuery<RequestRow>(
          client,
          `SELECT api_consumer_access_request_id::text AS id,
            requester_app_user_id::text AS "requesterAccountId", consumer_name AS name,
            intended_use AS "intendedUse", request_state AS state, created_at AS "createdAt",
            reviewed_at AS "reviewedAt", null::text AS "reviewedById",
            null::text AS "reviewedByName", api_consumer_id::text AS "consumerId"
           FROM api_consumer_access_request WHERE api_consumer_access_request_id = $1 FOR UPDATE`,
          [requestId],
        );
        const request = locked.rows[0];
        if (!request) throw new ApiAccessRequestNotFoundError();
        if (request.state !== 'pending') throw new ApiAccessConflictError();
        let consumerId: string | null = null;
        if (input.decision === 'approved') {
          const inserted = await executeQuery<{ id: string }>(
            client,
            `INSERT INTO api_consumer (owner_app_user_id, name, rate_limit_per_minute, daily_quota)
             VALUES ($1, $2, $3, $4) RETURNING api_consumer_id::text AS id`,
            [request.requesterAccountId, request.name, input.rateLimitPerMinute, input.dailyQuota],
          );
          consumerId = inserted.rows[0]!.id;
        }
        await executeQuery(
          client,
          `UPDATE api_consumer_access_request SET request_state = $2, api_consumer_id = $3,
            reviewed_by_app_user_id = $4, reviewed_at = now(), review_reason = $5
           WHERE api_consumer_access_request_id = $1`,
          [requestId, input.decision, consumerId, adminId, input.reviewReason ?? null],
        );
        return readRequest(client, requestId);
      });
    },
    async listConsumers() {
      const result = await executeQuery<{ id: string }>(
        pool,
        `SELECT api_consumer_id::text AS id FROM api_consumer ORDER BY api_consumer_id`,
      );
      return Promise.all(result.rows.map(({ id }) => readConsumer(pool, id)));
    },
    async updateLimits(consumerId, rateLimitPerMinute, dailyQuota) {
      const updated = await executeQuery(
        pool,
        `UPDATE api_consumer SET rate_limit_per_minute = $2, daily_quota = $3 WHERE api_consumer_id = $1`,
        [consumerId, rateLimitPerMinute, dailyQuota],
      );
      if (updated.rowCount !== 1) throw new ApiAccessRequestNotFoundError();
      return readConsumer(pool, consumerId);
    },
    async revokeAnyKey(consumerId, keyId) {
      const result = await executeQuery(
        pool,
        `UPDATE api_consumer_key SET revoked_at = now()
         WHERE api_consumer_id = $1 AND api_consumer_key_id = $2 AND revoked_at IS NULL`,
        [consumerId, keyId],
      );
      if (result.rowCount !== 1) throw new ApiAccessRequestNotFoundError();
    },
  };
}

export function createLazyApiAccessRepository(): ApiAccessRepository {
  let repository: ApiAccessRepository | undefined;
  const resolved = () => (repository ??= createApiAccessRepository());
  return {
    createRequest: (...args) => resolved().createRequest(...args),
    getOwn: (...args) => resolved().getOwn(...args),
    listPending: (...args) => resolved().listPending(...args),
    decide: (...args) => resolved().decide(...args),
    listConsumers: (...args) => resolved().listConsumers(...args),
    updateLimits: (...args) => resolved().updateLimits(...args),
    revokeAnyKey: (...args) => resolved().revokeAnyKey(...args),
  };
}

