  const result = await executeQuery<CompetitionRecord>(
    executor,
    `
      SELECT
        competition_id::text AS "competitionId",
        name
      FROM competition
      WHERE competition_id = $1
    `,
    [competitionId],
  );

  return result.rows[0] ?? null;
}
===== SEASONS =====
import { executeQuery, getDatabasePool, type QueryExecutor } from '../../database';

export interface SeasonRecord {
  competitionId: string;
  competitionName: string;
  label: string;
}

export interface SeasonListOptions {
  limit: number;
  competitionId?: string;
  name?: string;
  after?: {
    competitionId: string;
    label: string;
  };
}

export interface SeasonPage {
  records: SeasonRecord[];
  hasMore: boolean;
  totalRecords: number;
}

export async function listSeasons(
  options: SeasonListOptions,
  executor: QueryExecutor = getDatabasePool(),
): Promise<SeasonPage> {
  const innerConditions = ['f.competition_id IS NOT NULL'];
  // Split so the total reflects the filters (name) but not the cursor
  // position: paging further through the same filtered set must not
  // change how many pages it reports.
  const filterConditions: string[] = [];
  const cursorConditions: string[] = [];
  const values: unknown[] = [];

  if (options.competitionId) {
    values.push(options.competitionId);
    innerConditions.push(`f.competition_id = $${values.length}::bigint`);
  }

  if (options.name) {
    values.push(`%${options.name}%`);
    filterConditions.push(`(s.season ILIKE $${values.length} OR c.name ILIKE $${values.length})`);
  }

  if (options.after) {
    values.push(options.after.competitionId);
    const competitionParameter = values.length;

    values.push(options.after.label);
    const seasonParameter = values.length;

    cursorConditions.push(
      `(competition_id, season) > ($${competitionParameter}::bigint, $${seasonParameter}::text)`,
    );
  }

  values.push(options.limit + 1);
  const limitParameter = values.length;

  const filterWhere = filterConditions.length > 0 ? `WHERE ${filterConditions.join(' AND ')}` : '';
  const cursorWhere = cursorConditions.length > 0 ? `WHERE ${cursorConditions.join(' AND ')}` : '';

  const result = await executeQuery<SeasonRecord & { totalRecords: number }>(
    executor,
    `
      WITH seasons AS (
        SELECT DISTINCT
          f.competition_id,
          f.season
        FROM fixture f
        WHERE ${innerConditions.join(' AND ')}
      ),
      filtered_seasons AS (
        SELECT
          s.competition_id,
          s.season,
          c.name AS competition_name,
          COUNT(*) OVER()::integer AS "totalRecords"
        FROM seasons s
        INNER JOIN competition c
          ON c.competition_id = s.competition_id
        ${filterWhere}
      )
      SELECT
        competition_id::text AS "competitionId",
        competition_name AS "competitionName",
        season AS label,
        "totalRecords"
      FROM filtered_seasons
      ${cursorWhere}
      ORDER BY competition_id ASC, season ASC
      LIMIT $${limitParameter}
    `,
    values,
  );

  return {
    records: result.rows.slice(0, options.limit),
    hasMore: result.rows.length > options.limit,
    totalRecords: result.rows[0]?.totalRecords ?? 0,
  };
}

export async function findSeason(
  competitionId: string,
  label: string,
  executor: QueryExecutor = getDatabasePool(),
): Promise<SeasonRecord | null> {
  const result = await executeQuery<SeasonRecord>(
    executor,
    `
      SELECT
        f.competition_id::text AS "competitionId",
        c.name AS "competitionName",
        f.season AS label
      FROM fixture f
      INNER JOIN competition c
        ON c.competition_id = f.competition_id
      WHERE f.competition_id = $1::bigint
        AND f.season = $2::text
      LIMIT 1
    `,
    [competitionId, label],
  );

  return result.rows[0] ?? null;
}
===== COMPETITORS =====
import { executeQuery, getDatabasePool, type QueryExecutor } from '../../database';

export interface CompetitorRecord {
  competitorId: string;
  name: string;
}

export interface CompetitorListOptions {
  limit: number;
  competitionId?: string;
  season?: string;
  name?: string;
  after?: {
    name: string;
    competitorId: string;
  };
}

export interface CompetitorPage {
  records: CompetitorRecord[];
  hasMore: boolean;
}

export async function listCompetitors(
  options: CompetitorListOptions,
  executor: QueryExecutor = getDatabasePool(),
): Promise<CompetitorPage> {
  const conditions: string[] = [];
  const values: unknown[] = [];

  if (options.name) {
    values.push(`%${options.name}%`);
    conditions.push(`t.name ILIKE $${values.length}`);
  }

  if (options.competitionId || options.season) {
    const fixtureConditions = ['ft.team_id = t.team_id'];

    if (options.competitionId) {
      values.push(options.competitionId);
      fixtureConditions.push(`f.competition_id = $${values.length}::bigint`);
    }

    if (options.season) {
      values.push(options.season);
      fixtureConditions.push(`f.season = $${values.length}::text`);
    }

    conditions.push(`
      EXISTS (
        SELECT 1
        FROM fixture_team ft
        INNER JOIN fixture f
          ON f.fixture_id = ft.fixture_id
        WHERE ${fixtureConditions.join(' AND ')}
      )
    `);
  }

  if (options.after) {
    values.push(options.after.name);
    const nameParameter = values.length;

    values.push(options.after.competitorId);
    const idParameter = values.length;

    conditions.push(`(t.name, t.team_id) > ($${nameParameter}::text, $${idParameter}::bigint)`);
  }

  values.push(options.limit + 1);
  const limitParameter = values.length;

  const where = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';

  const result = await executeQuery<CompetitorRecord>(
    executor,
    `
      SELECT
        t.team_id::text AS "competitorId",
        t.name
      FROM team t
      ${where}
      ORDER BY t.name ASC, t.team_id ASC
      LIMIT $${limitParameter}
    `,
    values,
  );

  return {
    records: result.rows.slice(0, options.limit),
    hasMore: result.rows.length > options.limit,
  };
}

export async function findCompetitorById(
  competitorId: string,
  executor: QueryExecutor = getDatabasePool(),
): Promise<CompetitorRecord | null> {
  const result = await executeQuery<CompetitorRecord>(
    executor,
    `
      SELECT
        team_id::text AS "competitorId",
        name
      FROM team
      WHERE team_id = $1::bigint
    `,
    [competitorId],
  );

  return result.rows[0] ?? null;
}

